insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('5c23ca51-2895-44a4-bf07-6a05b8870480', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Disability, health equity, and physical activity participation', 'Adapted physical activity is about participation, dignity, and health, not simply modified exercises. This section frames disability-inclusive movement as a public health, education, sport, and human rights issue.', 0),
  ('9d661540-9f47-486f-8827-e300576ede76', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '5c23ca51-2895-44a4-bf07-6a05b8870480', 'subtopic'::public.curated_course_node_type, 'Participation, health, and belonging', 'Students learn why access to movement matters for physical health, social connection, self-efficacy, and lifelong wellbeing.', 0),
  ('783f1f63-0064-4722-bddc-235e3c5ad9ac', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '9d661540-9f47-486f-8827-e300576ede76', 'concept'::public.curated_course_node_type, 'Physical activity disparities and disability-related barriers', null, 0),
  ('61789233-0eaa-49cb-9d79-0153f588b73c', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '9d661540-9f47-486f-8827-e300576ede76', 'concept'::public.curated_course_node_type, 'Health promotion, chronic disease prevention, and quality of life', null, 1),
  ('03326ddb-7c43-4105-acaa-ed20d42d20cd', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '9d661540-9f47-486f-8827-e300576ede76', 'concept'::public.curated_course_node_type, 'Belonging, autonomy, competence, and self-determination', null, 2),
  ('66d21bef-b197-478b-a485-ebd0cc70fbbb', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '9d661540-9f47-486f-8827-e300576ede76', 'concept'::public.curated_course_node_type, 'School, recreation, sport, fitness, and community participation pathways', null, 3),
  ('e3060499-465f-4f3c-b6f0-bdffb15460ce', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '5c23ca51-2895-44a4-bf07-6a05b8870480', 'subtopic'::public.curated_course_node_type, 'Equity barriers and systems thinking', 'The gist is to see barriers as design problems in environments and systems, not deficits located only in the person.', 1),
  ('b2b93272-ecdd-46e3-bd6e-ae0a603eb5c6', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'e3060499-465f-4f3c-b6f0-bdffb15460ce', 'concept'::public.curated_course_node_type, 'Transportation, cost, staffing, policy, and facility barriers', null, 0),
  ('57b5b4b2-80d9-46de-8f26-2cfa717972e3', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'e3060499-465f-4f3c-b6f0-bdffb15460ce', 'concept'::public.curated_course_node_type, 'Ableism, stigma, low expectations, and exclusionary norms', null, 1),
  ('f9abde73-26db-42c4-b343-15ca2b6eaee3', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'e3060499-465f-4f3c-b6f0-bdffb15460ce', 'concept'::public.curated_course_node_type, 'Intersectionality across disability, race, gender, class, and language', null, 2),
  ('85c3a0f5-14f4-4b0b-bb1b-5126d53b390c', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'e3060499-465f-4f3c-b6f0-bdffb15460ce', 'concept'::public.curated_course_node_type, 'Program-level strategies for equitable access and retention', null, 3),
  ('a0bdab64-6f68-4555-81a0-fc60bbb4cfd4', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Legal, ethical, and professional foundations: ADA, IDEA, Section 504, and inclusion', 'Inclusive practice has legal and ethical foundations. This section helps students understand the rules and professional duties that shape access, accommodations, and participation.', 1),
  ('f41f536f-81c2-4834-ad33-236f49f71274', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'a0bdab64-6f68-4555-81a0-fc60bbb4cfd4', 'subtopic'::public.curated_course_node_type, 'Core legal frameworks', 'Students learn the main legal concepts that govern disability access in schools, public programs, and community settings.', 0),
  ('545523da-7943-4c77-a5b8-e4f69d9e4990', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'f41f536f-81c2-4834-ad33-236f49f71274', 'concept'::public.curated_course_node_type, 'Americans with Disabilities Act and reasonable accommodation', null, 0),
  ('933c1f3a-7803-4383-a789-a394ddec1020', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'f41f536f-81c2-4834-ad33-236f49f71274', 'concept'::public.curated_course_node_type, 'Individuals with Disabilities Education Act and adapted physical education', null, 1),
  ('684b5e0a-472f-4ae6-8c50-9385359b0d22', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'f41f536f-81c2-4834-ad33-236f49f71274', 'concept'::public.curated_course_node_type, 'Section 504, least restrictive environment, and equal access', null, 2),
  ('8d0b2576-e434-499a-9a2e-b68441c151f8', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'f41f536f-81c2-4834-ad33-236f49f71274', 'concept'::public.curated_course_node_type, 'Individualized Education Programs, service delivery, and documentation', null, 3),
  ('77caad06-767a-4965-8ec9-9de05999db7b', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'a0bdab64-6f68-4555-81a0-fc60bbb4cfd4', 'subtopic'::public.curated_course_node_type, 'Ethical and professional practice', 'The point is to make inclusion defensible, respectful, and aligned with professional standards rather than symbolic.', 1),
  ('3077c203-5ad1-41b7-a490-b2aa6ca5e742', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '77caad06-767a-4965-8ec9-9de05999db7b', 'concept'::public.curated_course_node_type, 'Informed consent, assent, privacy, and confidentiality', null, 0),
  ('759c0062-fa84-40f9-bb91-0a82ac0f883b', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '77caad06-767a-4965-8ec9-9de05999db7b', 'concept'::public.curated_course_node_type, 'Risk-benefit decisions and duty of care', null, 1),
  ('07ca4e5d-05be-4d17-9322-4dc91c9306c9', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '77caad06-767a-4965-8ec9-9de05999db7b', 'concept'::public.curated_course_node_type, 'Scope of practice, referral, and interdisciplinary collaboration', null, 2),
  ('4bb3102f-97c5-4f26-98b7-90d8d0e1cd7a', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '77caad06-767a-4965-8ec9-9de05999db7b', 'concept'::public.curated_course_node_type, 'Professional advocacy and accountability for inclusive environments', null, 3),
  ('116d6610-0750-4ea0-96b7-d9e54616a14e', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Disability models, identity, person-centered language, and cultural humility', 'How practitioners think and speak about disability shapes the programs they build. This section develops respectful, participant-centered, culturally humble practice.', 2),
  ('98e77604-9b28-4121-89bb-44cc08417abf', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '116d6610-0750-4ea0-96b7-d9e54616a14e', 'subtopic'::public.curated_course_node_type, 'Models of disability and identity', 'Students learn to compare medical, social, biopsychosocial, and rights-based models and apply them to program decisions.', 0),
  ('fc53530a-7899-4571-a083-308da6d24fe9', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '98e77604-9b28-4121-89bb-44cc08417abf', 'concept'::public.curated_course_node_type, 'Medical, social, and ecological perspectives', null, 0),
  ('7f6cfb1f-9c04-437b-a2e4-84a214cba2be', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '98e77604-9b28-4121-89bb-44cc08417abf', 'concept'::public.curated_course_node_type, 'Disability culture, pride, identity, and lived experience', null, 1),
  ('f8cd0d1f-f1f6-4904-ae9d-117c9de44e2e', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '98e77604-9b28-4121-89bb-44cc08417abf', 'concept'::public.curated_course_node_type, 'Strengths-based versus deficit-based planning', null, 2),
  ('52cf033e-ced9-499a-9f1f-8b0032d8b5d9', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '98e77604-9b28-4121-89bb-44cc08417abf', 'concept'::public.curated_course_node_type, 'Listening to participants, families, and disability communities', null, 3),
  ('91893493-7a3c-4729-a3d3-d8f8128572a5', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '116d6610-0750-4ea0-96b7-d9e54616a14e', 'subtopic'::public.curated_course_node_type, 'Language and cultural humility', 'The gist is to communicate respectfully while recognizing that preferences vary by person, culture, and context.', 1),
  ('772df468-9bb7-4b4a-b856-f8ca2367ba50', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '91893493-7a3c-4729-a3d3-d8f8128572a5', 'concept'::public.curated_course_node_type, 'Person-first and identity-first language preferences', null, 0),
  ('568d1872-32b8-4b58-996a-0a14e44e9d42', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '91893493-7a3c-4729-a3d3-d8f8128572a5', 'concept'::public.curated_course_node_type, 'Avoiding inspiration narratives, pity, and low expectations', null, 1),
  ('ab54f506-136b-4b98-8cc4-2a187e89e0e8', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '91893493-7a3c-4729-a3d3-d8f8128572a5', 'concept'::public.curated_course_node_type, 'Culturally responsive coaching and family engagement', null, 2),
  ('e230b991-d0b4-4c42-8dd1-c10e14241f1c', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '91893493-7a3c-4729-a3d3-d8f8128572a5', 'concept'::public.curated_course_node_type, 'Reflective practice, bias checks, and feedback loops', null, 3),
  ('e9a4b2e6-e9fc-45fb-ac84-e90cf5cd6bfc', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Intellectual disability, developmental disability, and neurodiversity', 'Participants with intellectual and developmental disabilities often need changes in instruction, pacing, communication, and environment. This section focuses on practical teaching that supports autonomy and success.', 3),
  ('2ad2e128-8345-4059-8393-0266ad387e88', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'e9a4b2e6-e9fc-45fb-ac84-e90cf5cd6bfc', 'subtopic'::public.curated_course_node_type, 'Learning, communication, and motor planning adaptations', 'Students learn to break activities into accessible parts while preserving meaningful challenge and choice.', 0),
  ('9f64383a-a698-4453-ad02-22c90e3a2096', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '2ad2e128-8345-4059-8393-0266ad387e88', 'concept'::public.curated_course_node_type, 'Task analysis, chaining, prompting, fading, and visual supports', null, 0),
  ('d49e8f1c-7c96-4a24-a24a-48ce02d4edbc', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '2ad2e128-8345-4059-8393-0266ad387e88', 'concept'::public.curated_course_node_type, 'Concrete instructions, modeling, repetition, and consistent routines', null, 1),
  ('287ec528-b618-47b5-91df-89c9b6dfb5fe', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '2ad2e128-8345-4059-8393-0266ad387e88', 'concept'::public.curated_course_node_type, 'Motor planning, coordination, balance, and movement confidence', null, 2),
  ('8e10252a-228f-4469-994d-d949eb49a20f', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '2ad2e128-8345-4059-8393-0266ad387e88', 'concept'::public.curated_course_node_type, 'Choice-making, self-monitoring, and participant voice', null, 3),
  ('8a92c929-547c-4516-ad22-f5f9bd16d941', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'e9a4b2e6-e9fc-45fb-ac84-e90cf5cd6bfc', 'subtopic'::public.curated_course_node_type, 'Neurodiversity and self-regulation', 'The point is to support participation for autistic and neurodivergent participants without forcing conformity or ignoring sensory needs.', 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e6e7a423-ba9e-4a0a-abc2-46dc149d0472', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a92c929-547c-4516-ad22-f5f9bd16d941', 'concept'::public.curated_course_node_type, 'Sensory profiles, predictability, transitions, and regulation supports', null, 0),
  ('a6ab6a58-d1a7-4f79-ba1a-2d00af316404', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a92c929-547c-4516-ad22-f5f9bd16d941', 'concept'::public.curated_course_node_type, 'Executive function, attention, motivation, and fatigue', null, 1),
  ('aaa3b186-f3fe-45ff-90f4-8a34dee40271', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a92c929-547c-4516-ad22-f5f9bd16d941', 'concept'::public.curated_course_node_type, 'Communication preferences and augmentative supports', null, 2),
  ('e815bbb5-2cf8-41aa-9e18-b6d6d2354dcc', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a92c929-547c-4516-ad22-f5f9bd16d941', 'concept'::public.curated_course_node_type, 'Positive behavior support and trauma-informed instruction', null, 3),
  ('eee519cd-f7a4-46f3-83e9-046aaa70de7e', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Physical disability, mobility impairment, chronic health conditions, and medical considerations', 'Physical and health-related disabilities require thoughtful programming around safety, function, fatigue, equipment, and medical risk. This section links kinesiology knowledge to inclusive participation.', 4),
  ('0ec05535-9445-47e5-8d59-e55ca3cc4e7c', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'eee519cd-f7a4-46f3-83e9-046aaa70de7e', 'subtopic'::public.curated_course_node_type, 'Mobility, neuromuscular, and orthopedic adaptations', 'Students learn to adapt movement for varied strength, range of motion, balance, coordination, and mobility-device use.', 0),
  ('c439ff60-e7cd-4be1-abb0-6590b1bfd625', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '0ec05535-9445-47e5-8d59-e55ca3cc4e7c', 'concept'::public.curated_course_node_type, 'Cerebral palsy, spinal cord injury, limb difference, arthritis, and neuromuscular conditions', null, 0),
  ('d853f8e6-0ab2-4c54-8ee0-8ef214d95863', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '0ec05535-9445-47e5-8d59-e55ca3cc4e7c', 'concept'::public.curated_course_node_type, 'Wheelchair skills, transfers, positioning, and pressure management awareness', null, 1),
  ('a7064685-1f93-490d-b896-9867ab246b8d', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '0ec05535-9445-47e5-8d59-e55ca3cc4e7c', 'concept'::public.curated_course_node_type, 'Strength, flexibility, balance, endurance, and mobility modifications', null, 2),
  ('5b162ed4-c518-486d-8c49-4f1c20431ab1', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '0ec05535-9445-47e5-8d59-e55ca3cc4e7c', 'concept'::public.curated_course_node_type, 'Pain, spasticity, contracture risk, and fatigue management', null, 3),
  ('5f24738d-0b39-4a72-89c4-ace9b90b6da4', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'eee519cd-f7a4-46f3-83e9-046aaa70de7e', 'subtopic'::public.curated_course_node_type, 'Chronic health and exercise safety', 'The gist is to plan activity around medical considerations while avoiding unnecessary exclusion.', 1),
  ('0ad0aca9-3cff-4d55-bef7-34c39c7f5f63', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '5f24738d-0b39-4a72-89c4-ace9b90b6da4', 'concept'::public.curated_course_node_type, 'Cardiometabolic, pulmonary, seizure, and autonomic considerations', null, 0),
  ('2912b598-3d5e-4b4c-b1a9-d25a1c0ab019', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '5f24738d-0b39-4a72-89c4-ace9b90b6da4', 'concept'::public.curated_course_node_type, 'Medication effects, hydration, heat illness, and exertion monitoring', null, 1),
  ('c839bc6a-397c-4888-b1c0-5f1ac959eb55', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '5f24738d-0b39-4a72-89c4-ace9b90b6da4', 'concept'::public.curated_course_node_type, 'Contraindications, precautions, and emergency action plans', null, 2),
  ('080a3cc0-2f28-415a-8aaa-3d2d657adfcf', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '5f24738d-0b39-4a72-89c4-ace9b90b6da4', 'concept'::public.curated_course_node_type, 'Referral and communication with health professionals', null, 3),
  ('90e04c13-e530-4394-840a-150ac576741b', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Sensory disabilities, communication access, and environmental adaptation', 'Inclusive physical activity depends on information access. This section teaches students to adapt cues, space, sound, lighting, touch, and communication so participation is understandable and safe.', 5),
  ('66212437-4022-467b-aab6-9a672436a26e', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '90e04c13-e530-4394-840a-150ac576741b', 'subtopic'::public.curated_course_node_type, 'Visual and hearing disability adaptations', 'Students learn to make instruction and environments accessible when visual or auditory information is limited or processed differently.', 0),
  ('2b536b07-09a7-4107-b5d8-6892f2bec145', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '66212437-4022-467b-aab6-9a672436a26e', 'concept'::public.curated_course_node_type, 'Tactile, auditory, visual, and partner-based cueing', null, 0),
  ('88d9582a-abb7-41b4-8ab6-9e02d569da34', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '66212437-4022-467b-aab6-9a672436a26e', 'concept'::public.curated_course_node_type, 'Orientation and mobility, safe boundaries, and spatial mapping', null, 1),
  ('a704249b-32bd-4982-90fe-4268291cedd1', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '66212437-4022-467b-aab6-9a672436a26e', 'concept'::public.curated_course_node_type, 'Captioning, sign language access, visual schedules, and demonstration placement', null, 2),
  ('85b180b3-fe15-4e97-a9ff-30f1fc5ecd70', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '66212437-4022-467b-aab6-9a672436a26e', 'concept'::public.curated_course_node_type, 'Equipment modifications such as beeping balls, contrast, texture, and markers', null, 3),
  ('86faa17e-e24f-48c6-9ac6-778277f77728', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '90e04c13-e530-4394-840a-150ac576741b', 'subtopic'::public.curated_course_node_type, 'Sensory processing and communication access', 'The point is to reduce environmental overload and build communication systems that support independence.', 1),
  ('f44ec945-7312-4ba2-afc9-5b0eb5a80cd5', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '86faa17e-e24f-48c6-9ac6-778277f77728', 'concept'::public.curated_course_node_type, 'Noise, lighting, crowding, texture, vestibular input, and proprioceptive needs', null, 0),
  ('69fd24e2-7609-48a3-a4a6-707cf5932533', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '86faa17e-e24f-48c6-9ac6-778277f77728', 'concept'::public.curated_course_node_type, 'Communication boards, gestures, demonstrations, and assistive communication', null, 1),
  ('fb7ed6c7-3e7d-4b56-a3a0-6a31f5873ed7', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '86faa17e-e24f-48c6-9ac6-778277f77728', 'concept'::public.curated_course_node_type, 'Preparation, previewing, quiet spaces, and sensory breaks', null, 2),
  ('046044cc-d331-4e22-913c-ff8c3c23625d', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '86faa17e-e24f-48c6-9ac6-778277f77728', 'concept'::public.curated_course_node_type, 'Emergency communication and safety signals', null, 3),
  ('be582587-a41a-4c6f-91cd-e113e11f78f8', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Aging, lifespan adaptation, and adapted activity for older adults', 'Adapted physical activity spans the lifespan. This section helps students translate inclusion principles to aging, frailty, chronic disease, cognition, and community participation.', 6),
  ('8a1e9836-9e39-45cf-b184-564e5a6289df', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'be582587-a41a-4c6f-91cd-e113e11f78f8', 'subtopic'::public.curated_course_node_type, 'Aging physiology and functional adaptation', 'Students learn how aging affects strength, balance, mobility, cognition, confidence, and training response.', 0),
  ('e6dd27c5-c46e-4721-91a3-3abc20d7054c', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a1e9836-9e39-45cf-b184-564e5a6289df', 'concept'::public.curated_course_node_type, 'Sarcopenia, osteoporosis, arthritis, cardiometabolic disease, and fall risk', null, 0),
  ('2e346049-f48b-4a95-8d23-c09dd6e1f44f', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a1e9836-9e39-45cf-b184-564e5a6289df', 'concept'::public.curated_course_node_type, 'Balance, gait, power, flexibility, and functional movement training', null, 1),
  ('11e2b4a7-860e-42f3-94c2-ca6b14ca6550', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a1e9836-9e39-45cf-b184-564e5a6289df', 'concept'::public.curated_course_node_type, 'Cognitive impairment, motivation, social isolation, and fear of falling', null, 2),
  ('41ff6636-9050-446a-a2e9-cb4cb9843d6f', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '8a1e9836-9e39-45cf-b184-564e5a6289df', 'concept'::public.curated_course_node_type, 'Progression, regression, recovery, and monitoring for older adults', null, 3),
  ('fc422edc-e049-45c9-a6b9-d0ff5c1c9c22', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'be582587-a41a-4c6f-91cd-e113e11f78f8', 'subtopic'::public.curated_course_node_type, 'Lifespan programming and community supports', 'The gist is to create movement opportunities that support independence, social connection, and health over time.', 1),
  ('267fc1aa-273f-43eb-9e79-641826e10beb', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc422edc-e049-45c9-a6b9-d0ff5c1c9c22', 'concept'::public.curated_course_node_type, 'Home, senior center, clinical, fitness, and community program settings', null, 0),
  ('c739cd0c-ed53-4ec6-9dc0-2616ccc6952a', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc422edc-e049-45c9-a6b9-d0ff5c1c9c22', 'concept'::public.curated_course_node_type, 'Caregiver involvement and transportation supports', null, 1),
  ('e3f23383-5acd-4afd-8050-ad5849923150', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc422edc-e049-45c9-a6b9-d0ff5c1c9c22', 'concept'::public.curated_course_node_type, 'Adapted group fitness, aquatic activity, walking programs, and chair-based options', null, 2),
  ('f6ca73a0-c554-4107-acb9-45bf2368433d', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc422edc-e049-45c9-a6b9-d0ff5c1c9c22', 'concept'::public.curated_course_node_type, 'Outcome goals tied to daily living and participation', null, 3),
  ('82cee4d6-3ba7-4c0f-a914-6eb7ab01c5d0', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Assessment, screening, goal setting, and individualized programming', 'Good adapted programming starts with assessment that respects the participant. This section teaches students to use screening and measurement to guide goals, not to gatekeep participation.', 7),
  ('fc0efaec-92e2-4220-a51a-db18a7a37561', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '82cee4d6-3ba7-4c0f-a914-6eb7ab01c5d0', 'subtopic'::public.curated_course_node_type, 'Assessment selection and interpretation', 'Students learn to choose valid, accessible, and meaningful assessment tools for varied participants and settings.', 0),
  ('a8bf1792-6eb1-4c3b-b08f-3b440791c45e', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc0efaec-92e2-4220-a51a-db18a7a37561', 'concept'::public.curated_course_node_type, 'Participant interview, health history, readiness, and preference assessment', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('7daf78ff-d487-4f0c-ad6d-51b9b6395e4d', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc0efaec-92e2-4220-a51a-db18a7a37561', 'concept'::public.curated_course_node_type, 'Motor skills, fitness, balance, mobility, and functional assessments', null, 1),
  ('ffe5b2a2-c313-4daf-b76f-ca902adbfe3a', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc0efaec-92e2-4220-a51a-db18a7a37561', 'concept'::public.curated_course_node_type, 'Reliability, validity, norms, accommodations, and ecological relevance', null, 2),
  ('da3ac4c8-a42f-4feb-bd19-c878304164b0', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'fc0efaec-92e2-4220-a51a-db18a7a37561', 'concept'::public.curated_course_node_type, 'Risk screening, contraindications, and referral triggers', null, 3),
  ('68543922-358a-42e9-9b8e-6967559aa8cd', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '82cee4d6-3ba7-4c0f-a914-6eb7ab01c5d0', 'subtopic'::public.curated_course_node_type, 'Goal setting and individualized plans', 'The point is to translate assessment into goals that are measurable, motivating, and relevant to real participation.', 1),
  ('5e05150a-fe76-419a-9172-912818218ece', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '68543922-358a-42e9-9b8e-6967559aa8cd', 'concept'::public.curated_course_node_type, 'SMART goals and participant-centered outcomes', null, 0),
  ('5d90a413-f45a-4dcc-854d-630da4a5d67b', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '68543922-358a-42e9-9b8e-6967559aa8cd', 'concept'::public.curated_course_node_type, 'Individualized education, recreation, fitness, or sport plans', null, 1),
  ('cd8e18d9-7c62-49a0-86d9-627e44bbe631', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '68543922-358a-42e9-9b8e-6967559aa8cd', 'concept'::public.curated_course_node_type, 'Progress monitoring, data collection, and adjustment', null, 2),
  ('52c7a910-4d0d-4c8a-be79-ecc3013349ad', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '68543922-358a-42e9-9b8e-6967559aa8cd', 'concept'::public.curated_course_node_type, 'Family, caregiver, teacher, coach, and clinician input', null, 3),
  ('06746434-cf51-4993-bf1e-892eb8c46fdf', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Inclusive instruction, universal design, behavior support, and coaching methods', 'Inclusive instruction is planned, not improvised. This section trains students to design sessions where multiple ways of moving, learning, communicating, and succeeding are available from the start.', 8),
  ('caffedab-a9e4-47c3-b6d1-db04f0564e05', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '06746434-cf51-4993-bf1e-892eb8c46fdf', 'subtopic'::public.curated_course_node_type, 'Universal design and inclusive teaching methods', 'Students learn to build flexibility into goals, rules, cues, equipment, space, and assessment before individual accommodations are added.', 0),
  ('d78bc2c4-0f81-4bf8-9846-056b390af8b4', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'caffedab-a9e4-47c3-b6d1-db04f0564e05', 'concept'::public.curated_course_node_type, 'Universal Design for Learning and multiple means of engagement, representation, and action', null, 0),
  ('6cfde51f-58f2-4607-a60b-8219691c4bdc', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'caffedab-a9e4-47c3-b6d1-db04f0564e05', 'concept'::public.curated_course_node_type, 'STEP framework: space, task, equipment, and people', null, 1),
  ('2061d6c9-3b7b-4a68-8ce5-8ee813ad0760', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'caffedab-a9e4-47c3-b6d1-db04f0564e05', 'concept'::public.curated_course_node_type, 'Differentiated instruction, peer support, stations, and small-group formats', null, 2),
  ('f2bd2f9d-74db-4312-8e96-5f2aa686c405', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'caffedab-a9e4-47c3-b6d1-db04f0564e05', 'concept'::public.curated_course_node_type, 'Cueing, feedback, modeling, and errorless learning strategies', null, 3),
  ('d5b06bb9-de49-4f9a-9716-f9dad5c157d2', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '06746434-cf51-4993-bf1e-892eb8c46fdf', 'subtopic'::public.curated_course_node_type, 'Motivation, behavior support, and coaching climate', 'The gist is to create psychologically safe activity settings that promote autonomy, competence, relatedness, and persistence.', 1),
  ('80dfcc7e-c471-4cf8-9b76-0818fdbcefd5', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'd5b06bb9-de49-4f9a-9716-f9dad5c157d2', 'concept'::public.curated_course_node_type, 'Autonomy-supportive coaching and motivational interviewing basics', null, 0),
  ('20110bf8-9a1c-4226-9f1b-c47746437479', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'd5b06bb9-de49-4f9a-9716-f9dad5c157d2', 'concept'::public.curated_course_node_type, 'Positive behavior support and antecedent strategies', null, 1),
  ('fb6cb079-2d89-4615-8191-0c66a701c70b', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'd5b06bb9-de49-4f9a-9716-f9dad5c157d2', 'concept'::public.curated_course_node_type, 'Trauma-informed session structure and de-escalation awareness', null, 2),
  ('f11481bc-3250-4c3a-bf9e-7d8d4a49fe4e', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'd5b06bb9-de49-4f9a-9716-f9dad5c157d2', 'concept'::public.curated_course_node_type, 'Celebrating progress without tokenism or lowered expectations', null, 3),
  ('53b2fa70-8210-419b-9586-755b8a89c00a', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Adapted sport, recreation, classification, and community participation', 'Adapted sport and recreation open pathways for competition, leisure, identity, travel, and community. This section covers both sport systems and everyday participation.', 9),
  ('b20bd964-6166-4074-8d17-b7f35581b60d', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '53b2fa70-8210-419b-9586-755b8a89c00a', 'subtopic'::public.curated_course_node_type, 'Adapted sport systems and classification', 'Students learn how adaptive sport is organized and how classification aims to support fair and meaningful competition.', 0),
  ('a6b6aaae-1815-4d6e-961e-5dfff103cdfa', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b20bd964-6166-4074-8d17-b7f35581b60d', 'concept'::public.curated_course_node_type, 'Paralympic, Special Olympics, Deaflympics, and community adaptive sport structures', null, 0),
  ('1ff9a598-3cb0-446a-84ab-95d3dc585160', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b20bd964-6166-4074-8d17-b7f35581b60d', 'concept'::public.curated_course_node_type, 'Classification purposes, eligibility, sport-specific criteria, and controversy', null, 1),
  ('bd1d3bb2-c054-4e57-acbe-3dc590f820d0', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b20bd964-6166-4074-8d17-b7f35581b60d', 'concept'::public.curated_course_node_type, 'Coaching roles, athlete development, safety, and equipment needs', null, 2),
  ('bffb9f13-0d6a-4b46-98d6-446c800b75a2', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b20bd964-6166-4074-8d17-b7f35581b60d', 'concept'::public.curated_course_node_type, 'Competition, recreation, lifelong participation, and athlete identity', null, 3),
  ('b55a5e80-9cf7-4fac-8917-84156909c43e', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '53b2fa70-8210-419b-9586-755b8a89c00a', 'subtopic'::public.curated_course_node_type, 'Recreation and community inclusion', 'The point is to connect participants with sustainable opportunities beyond a single class or lab setting.', 1),
  ('b7ae07ab-c479-429c-a82a-aa39b61b6517', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b55a5e80-9cf7-4fac-8917-84156909c43e', 'concept'::public.curated_course_node_type, 'Aquatics, outdoor recreation, dance, fitness, cycling, climbing, and play', null, 0),
  ('de855a6f-27c8-4f9b-99bd-f3ba88f1e2dc', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b55a5e80-9cf7-4fac-8917-84156909c43e', 'concept'::public.curated_course_node_type, 'Family-centered and peer-supported participation', null, 1),
  ('c46f15f5-701c-4b64-912a-415248578bc0', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b55a5e80-9cf7-4fac-8917-84156909c43e', 'concept'::public.curated_course_node_type, 'Program mapping, referral pathways, and community partnerships', null, 2),
  ('96394da2-bd09-4d45-bf71-d4b897f5fa14', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', 'b55a5e80-9cf7-4fac-8917-84156909c43e', 'concept'::public.curated_course_node_type, 'Transportation, cost, staffing, and retention supports', null, 3),
  ('708b9ee9-1b44-4bdd-abd6-900f8dd2f3de', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Programming, equipment, assistive technology, and facility accessibility', 'Adaptation often lives in the details: equipment, space, scheduling, staffing, and technology. This section teaches students to modify activity without diluting purpose.', 10),
  ('16f39ed2-ed04-450e-acc7-a43f8e36bcb1', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '708b9ee9-1b44-4bdd-abd6-900f8dd2f3de', 'subtopic'::public.curated_course_node_type, 'Equipment and assistive technology', 'Students learn to select, modify, and maintain tools that increase independence and participation.', 0),
  ('834f6571-fb0b-45a7-ace0-6b7bde1f04f4', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '16f39ed2-ed04-450e-acc7-a43f8e36bcb1', 'concept'::public.curated_course_node_type, 'Modified balls, targets, grips, straps, ramps, supports, and resistance tools', null, 0),
  ('e9024311-06ee-456b-bc3b-38429a2982d6', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '16f39ed2-ed04-450e-acc7-a43f8e36bcb1', 'concept'::public.curated_course_node_type, 'Wheelchairs, sport chairs, walkers, prosthetics, orthotics, and seating interfaces', null, 1),
  ('df43cbde-2c95-403b-ae80-e17a59bd3892', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '16f39ed2-ed04-450e-acc7-a43f8e36bcb1', 'concept'::public.curated_course_node_type, 'Wearables, apps, communication tools, and monitoring devices', null, 2),
  ('ef94f15e-2b7d-439a-bc67-46e33d966368', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '16f39ed2-ed04-450e-acc7-a43f8e36bcb1', 'concept'::public.curated_course_node_type, 'Fit, comfort, safety, cost, repair, and sanitation considerations', null, 3),
  ('4cc82316-6b08-4135-9051-a8b3070d3661', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '708b9ee9-1b44-4bdd-abd6-900f8dd2f3de', 'subtopic'::public.curated_course_node_type, 'Accessible program logistics and environments', 'The gist is to make spaces and routines usable before participants arrive.', 1),
  ('fef824c5-c42e-426a-b698-217da1e93014', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '4cc82316-6b08-4135-9051-a8b3070d3661', 'concept'::public.curated_course_node_type, 'Facility accessibility, surfaces, routes, signage, bathrooms, and changing areas', null, 0),
  ('c83cf411-2790-4527-948c-0c291a864ed9', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '4cc82316-6b08-4135-9051-a8b3070d3661', 'concept'::public.curated_course_node_type, 'Emergency access, supervision ratios, transitions, and traffic flow', null, 1),
  ('a82c4384-2855-4d6e-b9c1-e94cc4d1434f', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '4cc82316-6b08-4135-9051-a8b3070d3661', 'concept'::public.curated_course_node_type, 'Scheduling, staffing, transportation, and caregiver coordination', null, 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('2c583456-418d-4761-b259-6ff1077c2e74', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '4cc82316-6b08-4135-9051-a8b3070d3661', 'concept'::public.curated_course_node_type, 'Inclusive registration, waivers, intake forms, and accommodation requests', null, 3),
  ('72765947-08f0-456b-8200-31f0ec601357', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', null, 'topic'::public.curated_course_node_type, 'Program evaluation, safety, collaboration, advocacy, and leadership', 'An adapted physical activity professional improves systems, not only sessions. This final section develops evaluation, safety, teamwork, and advocacy habits.', 11),
  ('07e77753-0a63-4ef9-9385-5fe35d8094b3', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '72765947-08f0-456b-8200-31f0ec601357', 'subtopic'::public.curated_course_node_type, 'Evaluation, safety, and quality improvement', 'Students learn to measure whether programs are accessible, effective, safe, and valued by participants.', 0),
  ('d620622c-0ca9-4311-847c-65ee9fa1842a', 'a8d2e4c1-6b39-4f07-9a15-3e0c7d5b8f62', '07e77753-0a63-4ef9-9385-5fe35d8094b3', 'concept'::public.curated_course_node_type, 'Participation, retention, satisfaction, skill, fitness, and health metrics', null, 0),
